import {CartesianCoordinate as CC} from './cartesian-coordinate';
const frame=()=>new Promise<void>(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>r())));
const check=(ok:boolean,message:string)=>{if(!ok)throw new Error(message);};
export async function verifyCartesianBounds():Promise<string[]>{
 const cc=CC.make();cc.style.width='800px';cc.style.height='420px';cc.bind({showAxes:true});document.body.append(cc);await frame();cc.onSizeChange?.({width:800,height:420});const axes=()=>[...cc.shadowRoot!.querySelectorAll('std-cc-axis')];check(axes().length===26&&cc.querySelectorAll('std-cc-axis').length===2,'Default50 geometry/cardinality');const original=axes();
 for(const interval of [1e-6,Number.MIN_VALUE,NaN,Infinity,-1]){let rejected=false;try{cc.bind({showAxes:true,gridInterval:interval});}catch(e){rejected=e instanceof RangeError;}check(rejected,'Invalid interval accepted '+interval);check(axes().every((v,i)=>v===original[i]),'Invalid bind replaced valid grid');}
 cc.bind({showAxes:false,gridInterval:0});check(axes().length===0,'Explicit zero does not disable');cc.bind({showAxes:true});cc.onSizeChange?.({width:800,height:420});cc.remove();check(axes().length===0,'Detach retained generated grid');document.body.append(cc);await frame();check(axes().length===26,'Reconnect did not restore default grid');
 cc.onSizeChange?.({width:1e12,height:420});check(axes().length===0,'Oversized viewport not bounded');cc.onSizeChange?.({width:800,height:420});check(axes().length===26,'Density fallback did not recover');cc.recycle();await frame();const b=CC.make();check(b===cc,'Cartesian actual pool reuse');check(axes().length===0&&b.querySelectorAll('std-cc-axis').length===0,'Pooled grid/origin state retained');b.bind({showAxes:false});document.body.append(b);await frame();check(axes().length===0,'Successor inherited old grid');b.recycle();await frame();return ['Cartesian invalid/tiny/subnormal/nonfinite bind rejects before changing valid geometry','Default50, explicit off, bounded resize fallback, reconnect and pooled axis retirement'];
}
